import numpy as np

def voxel_downsample(points, size):
    """Replace all points that fall in the same cubic voxel of side `size` by their centroid.
    points: (n, 3) array. Voxel of a point: floor(coordinates / size). Return an (m, 3) array,
    one centroid per occupied voxel, in any order."""
    return np.asarray(points, dtype=float)

import numpy as np

def best_rigid_transform(P, Q):
    """Rotation R (det +1) and translation t minimising sum_i ||R p_i + t - q_i||^2.
    P, Q: (n, d) arrays of paired points, d = 2 or 3. Return (R, t)."""
    d = np.asarray(P).shape[1]
    return np.eye(d), np.zeros(d)
